import type { ReactNode } from "react";
import { Icon } from "@/icons";

type HumanReviewBannerProps = {
  title?: ReactNode;
  body?: ReactNode;
  onAccept?: () => void;
  onReject?: () => void;
  onEdit?: () => void;
  acceptLabel?: string;
  rejectLabel?: string;
  editLabel?: string;
};

/**
 * Human-in-the-loop accept/reject/edit banner.
 *
 * Sits above an AI-generated artifact and forces the officer to make
 * a decision before the draft can become an action. Every officer
 * decision should be recorded in the audit trail.
 */
export function HumanReviewBanner({
  title = "Officer review required",
  body = "This draft was generated by AI and must be reviewed before it becomes part of the record.",
  onAccept,
  onReject,
  onEdit,
  acceptLabel = "Accept",
  rejectLabel = "Reject",
  editLabel = "Edit",
}: HumanReviewBannerProps) {
  return (
    <div className="ai-review-banner" role="region" aria-label="Officer review">
      <span className="ai-review-banner__icon">
        <Icon name="shield" size={22} />
      </span>
      <div className="ai-review-banner__body">
        <div className="ai-review-banner__title">{title}</div>
        <div>{body}</div>
      </div>
      <div className="ai-review-banner__actions">
        {onEdit && (
          <button type="button" className="btn btn--outline btn--sm" onClick={onEdit}>
            {editLabel}
          </button>
        )}
        {onReject && (
          <button type="button" className="btn btn--dark btn--sm" onClick={onReject}>
            {rejectLabel}
          </button>
        )}
        {onAccept && (
          <button type="button" className="btn btn--primary btn--sm" onClick={onAccept}>
            {acceptLabel}
          </button>
        )}
      </div>
    </div>
  );
}
